<?php
declare(strict_types=1);
require_once __DIR__ . '/_bootstrap.php'; require_admin();
$pdo = db(); $q = trim((string) ($_GET['q'] ?? '')); $category = filter_input(INPUT_GET, 'category', FILTER_VALIDATE_INT) ?: 0; $page = max(1, filter_input(INPUT_GET, 'page', FILTER_VALIDATE_INT) ?: 1); $perPage = 20;
$where = []; $params = [];
if ($q !== '') { $where[] = '(r.name LIKE :q OR r.address LIKE :q)'; $params[':q'] = '%' . str_replace(['%', '_'], ['\\%', '\\_'], $q) . '%'; }
if ($category) { $where[] = 'r.category_id = :category'; $params[':category'] = $category; }
$condition = $where ? ' WHERE ' . implode(' AND ', $where) : '';
$count = $pdo->prepare('SELECT COUNT(*) FROM restaurants r' . $condition); $count->execute($params); $total = (int) $count->fetchColumn();
$stmt = $pdo->prepare('SELECT r.*, c.name AS category_name, c.slug AS category_slug, c.icon AS category_icon FROM restaurants r JOIN categories c ON c.id = r.category_id' . $condition . ' ORDER BY r.updated_at DESC LIMIT :limit OFFSET :offset'); foreach ($params as $key => $value) $stmt->bindValue($key, $value); $stmt->bindValue(':limit', $perPage, PDO::PARAM_INT); $stmt->bindValue(':offset', ($page - 1) * $perPage, PDO::PARAM_INT); $stmt->execute(); $rows = $stmt->fetchAll(); $categories = $pdo->query('SELECT id,name FROM categories ORDER BY sort_order,name')->fetchAll();
admin_header('Quán ăn'); ?>
<div class="admin-heading"><div><h1>Quản lý quán ăn</h1><p class="admin-note"><?= $total ?> quán trong hệ thống</p></div><a href="restaurant_form.php" class="btn btn--primary">+ Thêm quán</a></div>
<form class="admin-toolbar" method="get"><input class="admin-input" name="q" value="<?= h($q) ?>" placeholder="Tìm tên hoặc địa chỉ"><select class="admin-select" name="category"><option value="">Tất cả danh mục</option><?php foreach ($categories as $cat): ?><option value="<?= (int) $cat['id'] ?>" <?= $category === (int)$cat['id'] ? 'selected' : '' ?>><?= h($cat['name']) ?></option><?php endforeach; ?></select><button class="btn btn--ghost" type="submit">Lọc</button></form>
<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Quán ăn</th><th>Danh mục</th><th>Đánh giá</th><th>Giá</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?php if ($row['image_url']): ?><img class="admin-thumb" src="../<?= h($row['image_url']) ?>" alt=""><?php endif; ?><strong><?= h($row['name']) ?></strong><br><small><?= h($row['address']) ?></small></td><td><span style="display:inline-flex;align-items:center;gap:6px"><?= admin_category_icon($row['category_slug'] ?? $row['category_icon']) ?> <?= h($row['category_name']) ?></span></td><td><span style="display:inline-flex;align-items:center;gap:4px;font-weight:700"><?= admin_svg_icon('star') ?> <?= h($row['rating']) ?></span> <small style="color:var(--c-ink-faint)">(<?= (int)$row['rating_count'] ?>)</small></td><td><?= number_format((int)$row['price_min']/1000,0) ?>–<?= number_format((int)$row['price_max']/1000,0) ?>k</td><td><?= (int)$row['is_active'] ? 'Đang hiển thị' : 'Đã ẩn' ?></td><td><div class="actions"><a class="btn btn--ghost btn--sm" href="restaurant_form.php?id=<?= (int)$row['id'] ?>">Sửa</a><form method="post" action="restaurant_delete.php" class="inline"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="active" value="<?= (int)$row['is_active'] ? 0 : 1 ?>"><button class="btn btn--ghost btn--sm <?= (int)$row['is_active'] ? 'danger' : '' ?>" type="submit"><?= (int)$row['is_active'] ? 'Ẩn' : 'Hiện' ?></button></form></div></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="6">Không có quán nào phù hợp.</td></tr><?php endif; ?></tbody></table></div>
<?php $pages = max(1, (int) ceil($total / $perPage)); if ($pages > 1): ?><nav class="pagination" aria-label="Phân trang"><?php for ($p=1;$p<=$pages;$p++): ?><a href="?<?= h(http_build_query(['q'=>$q,'category'=>$category ?: null,'page'=>$p])) ?>" <?= $p===$page ? 'aria-current="page"' : '' ?>><?= $p ?></a><?php endfor; ?></nav><?php endif; admin_footer();

